<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Asyura\Auth;use Asyura\Security;use Asyura\View;
Auth::requireLogin($config['app_url']);if($_SERVER['REQUEST_METHOD']!=='POST'||!Security::verifyCsrf($_POST['csrf_token']??null)){http_response_code(403);exit('Invalid request');}$year=(int)($_POST['year']??0);if(($_POST['confirm_delete']??'no')!=='yes'){View::flash('「はい、削除します」が選択されていないため、削除しませんでした。','error');redirect(app_url('admin/?page=data'));}$check=$db->prepare('SELECT COUNT(*) FROM exports WHERE export_year=?');$check->execute([$year]);if(!(int)$check->fetchColumn()){View::flash('先に対象年をエクスポートしてください。','error');redirect(app_url('admin/?page=data'));}$start=sprintf('%04d-01-01 00:00:00',$year);$end=sprintf('%04d-01-01 00:00:00',$year+1);$defs=['raw_events'=>'occurred_at','daily_stats'=>'stat_date','daily_link_stats'=>'stat_date','referrer_stats'=>'stat_date','rss_distribution_history'=>'calculated_at','rss_distribution_batches'=>'calculated_at'];$db->beginTransaction();try{foreach($defs as $table=>$column){$stmt=$db->prepare("DELETE FROM {$table} WHERE {$column}>=? AND {$column}<?");$stmt->execute([$start,$end]);}$db->commit();View::flash($year.'年のDBデータを削除しました。アーカイブは残っています。');}catch(Throwable $e){$db->rollBack();View::flash('削除できませんでした。','error');}redirect(app_url('admin/?page=data'));
